def runs(cells):
    """split sorted (pos,line) cells into contiguous runs"""
    cells=sorted(cells); out=[]; cur=[cells[0]]
    for a,b in cells[1:]:
        if a==cur[-1][0]+1 and b==cur[-1][1]: cur.append((a,b))
        else: out.append(cur); cur=[(a,b)]
    out.append(cur); return out

